diff --git a/tests/notes.test.mjs b/tests/notes.test.mjs
index b43658e..c03f767 100644
--- a/tests/notes.test.mjs
+++ b/tests/notes.test.mjs
@@ -32,3 +32,30 @@ test('a note can be updated and deleted', async () => {
   assert.equal((await call('DELETE', `/notes/${note.id}`, 'ayse')).status, 204);
   assert.equal((await call('GET', `/notes/${note.id}`, 'ayse')).status, 404);
 });
+
+test('SALDIRI Güv-01.1: x-user yok veya boş ise 401', async () => {
+  for (const [m, p] of [['GET', '/notes'], ['POST', '/notes'], ['GET', '/notes/1'], ['PATCH', '/notes/1'], ['DELETE', '/notes/1']]) {
+    const body = m === 'POST' || m === 'PATCH' ? { title: 'x' } : undefined;
+    assert.equal((await call(m, p, undefined, body)).status, 401, `${m} ${p} başlıksız`);
+    assert.equal((await call(m, p, '   ', body)).status, 401, `${m} ${p} boş başlık`);
+  }
+  assert.equal((await fetch(base + '/notes', { headers: { 'x-user': '' } })).status, 401);
+});
+
+test('SALDIRI Güv-01.2: kullanıcı yalnız kendi notlarını listeler', async () => {
+  const a = await (await call('POST', '/notes', 'list-a', { title: 'a-notu' })).json();
+  await call('POST', '/notes', 'list-b', { title: 'b-notu' });
+  const list = await (await call('GET', '/notes', 'list-a')).json();
+  assert.ok(list.length > 0 && list.every((n) => n.owner === 'list-a'));
+  assert.ok(list.some((n) => n.id === a.id));
+});
+
+test('SALDIRI Güv-01.3: başkasının notu okunamaz, değiştirilemez, silinemez', async () => {
+  const note = await (await call('POST', '/notes', 'sahip', { title: 'gizli', body: 'sır' })).json();
+  assert.equal((await call('GET', `/notes/${note.id}`, 'saldirgan')).status, 404);
+  assert.equal((await call('PATCH', `/notes/${note.id}`, 'saldirgan', { title: 'hack' })).status, 404);
+  assert.equal((await call('DELETE', `/notes/${note.id}`, 'saldirgan')).status, 404);
+  const got = await (await call('GET', `/notes/${note.id}`, 'sahip')).json();
+  assert.equal(got.title, 'gizli');
+  assert.equal(got.body, 'sır');
+});

