diff --git a/tests/notes.test.mjs b/tests/notes.test.mjs
index b43658e..ef2c9c7 100644
--- a/tests/notes.test.mjs
+++ b/tests/notes.test.mjs
@@ -32,3 +32,36 @@ test('a note can be updated and deleted', async () => {
   assert.equal((await call('DELETE', `/notes/${note.id}`, 'ayse')).status, 204);
   assert.equal((await call('GET', `/notes/${note.id}`, 'ayse')).status, 404);
 });
+
+test('Ö-SEC.1 SALDIRI: x-user yok, boş veya boşluk ise 401', async () => {
+  for (const u of [undefined, '', '   ']) {
+    const h = { 'content-type': 'application/json', ...(u !== undefined ? { 'x-user': u } : {}) };
+    for (const [m, p] of [['GET', '/notes'], ['POST', '/notes'], ['GET', '/notes/1'], ['PATCH', '/notes/1'], ['DELETE', '/notes/1']]) {
+      const r = await fetch(base + p, { method: m, headers: h, body: m === 'POST' || m === 'PATCH' ? JSON.stringify({ title: 'x' }) : undefined });
