+  assert.equal((await call('DELETE', `/notes/${mine.id}`, 'veli')).status, 404);
+  const still = await (await call('GET', `/notes/${mine.id}`, 'ali')).json();
+  assert.equal(still.title, 'ali-gizli');
+});
+
+test('Ö-SEC.4 SALDIRI: PATCH ile sahiplik devredilemez', async () => {
+  const mine = await (await call('POST', '/notes', 'ali', { title: 'a' })).json();
+  await call('PATCH', `/notes/${mine.id}`, 'ali', { owner: 'veli', title: 'b' });
+  assert.equal((await call('GET', `/notes/${mine.id}`, 'veli')).status, 404);
+  assert.equal((await call('GET', `/notes/${mine.id}`, 'ali')).status, 200);
